import { Canvas, useFrame } from '@react-three/fiber'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import * as THREE from 'three'
import { Arwing, CameraRig, Reticle } from './Arwing'
import { Enemy } from './Enemy'
import { Laser } from './Laser'
import { SceneEffects } from './SceneEffects'
import { Terrain } from './Terrain'
import type {
  EnemyHandle,
  EnemySpawn,
  FlightRuntime,
  InputState,
  LaserHandle,
  LaserOwner,
  PlayerState,
  TeammateId,
  WorldState,
} from './types'

interface Encounter {
  at: number
  enemies: Array<Omit<EnemySpawn, 'id' | 'bornAt'>>
}

interface LaserSpec {
  id: string
  owner: LaserOwner
  origin: THREE.Vector3
}

const TEAM = [
  { id: 'lyra' as const, name: 'Lyra', role: 'scout' },
  { id: 'rook' as const, name: 'Rook', role: 'tactician' },
  { id: 'pip' as const, name: 'Pip', role: 'support' },
]

const ENCOUNTERS: Encounter[] = [
  {
    at: 0,
    enemies: [
      { variant: 'scout', x: -5, y: 2.2, z: -62, health: 1 },
      { variant: 'scout', x: 0, y: 3.3, z: -68, health: 1 },
      { variant: 'scout', x: 5, y: 1.8, z: -74, health: 1 },
    ],
  },
  {
    at: 42,
    enemies: [
      { variant: 'scout', x: -5.8, y: 1.4, z: -72, health: 1, target: 'lyra' },
      { variant: 'scout', x: -3.7, y: 1.2, z: -78, health: 1 },
      { variant: 'heavy', x: 4.6, y: 3.4, z: -84, health: 3 },
    ],
  },
  {
    at: 88,
    enemies: [
      { variant: 'turret', x: -7, y: -1.3, z: -68, health: 2 },
      { variant: 'turret', x: 0, y: -1.3, z: -86, health: 2 },
      { variant: 'turret', x: 7, y: -1.3, z: -76, health: 2 },
      { variant: 'scout', x: 0, y: 5, z: -98, health: 1, target: 'rook' },
    ],
  },
  {
    at: 148,
    enemies: [
      { variant: 'heavy', x: -5.5, y: 2.7, z: -76, health: 3 },
      { variant: 'heavy', x: 5.5, y: 2.7, z: -90, health: 3 },
      { variant: 'scout', x: -1.5, y: 4.8, z: -108, health: 1 },
      { variant: 'scout', x: 1.5, y: 4.8, z: -113, health: 1, target: 'pip' },
    ],
  },
  {
    at: 226,
    enemies: [
      { variant: 'turret', x: -7.4, y: -1.5, z: -74, health: 2 },
      { variant: 'turret', x: 7.4, y: -1.5, z: -82, health: 2 },
      { variant: 'heavy', x: 0, y: 4, z: -104, health: 3 },
    ],
  },
  {
    at: 314,
    enemies: [
      { variant: 'scout', x: -5.7, y: 3.5, z: -78, health: 1 },
      { variant: 'scout', x: 5.7, y: 3.5, z: -84, health: 1 },
      { variant: 'heavy', x: 0, y: 0.5, z: -106, health: 3 },
    ],
  },
  {
    at: 378,
    enemies: [{ variant: 'carrier', x: 0, y: 2.2, z: -96, health: 22 }],
  },
]

const initialPlayer = (): PlayerState => ({
  position: new THREE.Vector3(0, 0, 2.5),
  target: new THREE.Vector3(0, 0, 2.5),
  invincibleUntil: 0,
  barrel: { active: false, direction: 1, startedAt: 0 },
})

const initialWorld = (): WorldState => ({ distance: 0, speed: 24, boost: false })
const initialInput = (): InputState => ({ keys: new Set(), justPressed: new Set() })

export function Game() {
  const [runId, setRunId] = useState(0)
  const [running, setRunning] = useState(true)
  const [stageState, setStageState] = useState<'live' | 'won' | 'lost'>('live')
  const [score, setScore] = useState(0)
  const [shield, setShield] = useState(100)
  const [bombs, setBombs] = useState(3)
  const [status, setStatus] = useState('ESCORT THE CONVOY · CLEAR THE SKYLINE')
  const [distance, setDistance] = useState(0)
  const [bossHealth, setBossHealth] = useState(0)
  const [teammates, setTeammates] = useState<Record<TeammateId, boolean>>({ lyra: true, rook: true, pip: true })

  const input = useRef<InputState>(initialInput())
  const world = useRef<WorldState>(initialWorld())
  const player = useRef<PlayerState>(initialPlayer())
  const lasers = useRef(new Map<string, LaserHandle>())
  const enemies = useRef(new Map<string, EnemyHandle>())
  const encounterCursor = useRef(0)
  const spawnedEnemies = useRef<EnemySpawn[]>([])
  const lastShot = useRef(0)
  const lastHudUpdate = useRef(0)
  const gameOver = useRef(false)

  const [enemySpawns, setEnemySpawns] = useState<EnemySpawn[]>([])
  const [laserSpecs, setLaserSpecs] = useState<LaserSpec[]>([])

  const flight = useMemo<FlightRuntime>(() => ({
    input: input.current,
    world: world.current,
    player: player.current,
  }), [])

  const triggerBarrel = useCallback((direction: number) => {
    const now = performance.now() / 1000
    if (player.current.barrel.active || now < player.current.invincibleUntil) return
    player.current.barrel = { active: true, direction, startedAt: now }
    player.current.invincibleUntil = now + 0.9
    setStatus('BARREL ROLL · LASERS DEFLECTED')
  }, [])

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const code = event.code
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(code)) event.preventDefault()
      const now = performance.now() / 1000
      const horizontal = code === 'ArrowLeft' || code === 'KeyA' ? -1 : code === 'ArrowRight' || code === 'KeyD' ? 1 : 0
      if (!event.repeat) {
        input.current.justPressed.add(code)
        if (horizontal !== 0) {
          const last = Number((onKeyDown as unknown as { lastTap?: number }).lastTap ?? 0)
          if (now - last < 0.28) triggerBarrel(horizontal)
          ;(onKeyDown as unknown as { lastTap?: number }).lastTap = now
        }
      }
      input.current.keys.add(code)
    }
    const onKeyUp = (event: KeyboardEvent) => input.current.keys.delete(event.code)
    window.addEventListener('keydown', onKeyDown)
    window.addEventListener('keyup', onKeyUp)
    return () => {
      window.removeEventListener('keydown', onKeyDown)
      window.removeEventListener('keyup', onKeyUp)
      input.current.keys.clear()
      input.current.justPressed.clear()
    }
  }, [triggerBarrel])

  const spawnLaser = useCallback((owner: LaserOwner, origin: THREE.Vector3) => {
    const id = `${owner}-${performance.now()}-${Math.random()}`
    setLaserSpecs((current) => [...current, { id, owner, origin: origin.clone() }])
  }, [])

  const registerLaser = useCallback((handle: LaserHandle) => lasers.current.set(handle.id, handle), [])
  const unregisterLaser = useCallback((id: string) => lasers.current.delete(id), [])
  const expireLaser = useCallback((id: string) => {
    lasers.current.get(id)?.alive = false
    setLaserSpecs((current) => current.filter((laser) => laser.id !== id))
  }, [])

  const registerEnemy = useCallback((handle: EnemyHandle) => enemies.current.set(handle.id, handle), [])
  const unregisterEnemy = useCallback((id: string) => enemies.current.delete(id), [])

  const removeEnemy = useCallback((spawn: EnemySpawn) => {
    enemies.current.get(spawn.id)?.alive = false
    setEnemySpawns((current) => current.filter((enemy) => enemy.id !== spawn.id))
    spawnedEnemies.current = spawnedEnemies.current.filter((enemy) => enemy.id !== spawn.id)
    if (spawn.target) setStatus(`${spawn.target.toUpperCase()} COVERED · KEEP FORMATION`)
  }, [])

  const damagePlayer = useCallback((amount: number) => {
    if (gameOver.current) return
    setShield((current) => {
      const next = Math.max(0, current - amount)
      if (next === 0) {
        gameOver.current = true
        setStageState('lost')
        setRunning(false)
      }
      return next
    })
  }, [])

  const hitEnemy = useCallback((enemyId: string) => {
    const handle = enemies.current.get(enemyId)
    if (!handle?.alive) return
    const enemy = spawnedEnemies.current.find((candidate) => candidate.id === enemyId)
    if (!enemy) return
    handle.alive = false
    if (enemy.variant === 'carrier') {
      const nextHealth = Math.max(0, enemy.health - 1)
      setEnemySpawns((current) => current.map((candidate) => candidate.id === enemyId ? { ...candidate, health: nextHealth } : candidate))
      spawnedEnemies.current = spawnedEnemies.current.map((candidate) => candidate.id === enemyId ? { ...candidate, health: nextHealth } : candidate)
      setBossHealth(nextHealth)
      setScore((current) => current + 25)
      if (nextHealth <= 0) {
        setStatus('CARRIER CORE DESTROYED · SKYLINE SECURED')
        setStageState('won')
        setRunning(false)
        setEnemySpawns((current) => current.filter((candidate) => candidate.id !== enemyId))
      } else {
        setStatus(`CARRIER SYSTEM HIT · ${nextHealth} ARMOR REMAINS`)
        handle.alive = true
      }
      return
    }
    setScore((current) => current + (enemy.variant === 'heavy' ? 20 : enemy.variant === 'turret' ? 15 : 10))
    removeEnemy(enemy)
  }, [removeEnemy])

  useFrame((_state, delta) => {
    if (!running || gameOver.current) return
    const now = performance.now() / 1000
    world.current.boost = input.current.keys.has('ShiftLeft') || input.current.keys.has('ShiftRight')
    world.current.distance += delta * world.current.speed * (world.current.boost ? 1.75 : 1)

    while (encounterCursor.current < ENCOUNTERS.length && world.current.distance >= ENCOUNTERS[encounterCursor.current].at) {
      const encounter = ENCOUNTERS[encounterCursor.current]
      const spawned = encounter.enemies.map((enemy, index) => ({
        ...enemy,
        id: `encounter-${encounterCursor.current}-${index}`,
        bornAt: world.current.distance,
      }))
      spawnedEnemies.current = [...spawnedEnemies.current, ...spawned]
      setEnemySpawns((current) => [...current, ...spawned])
      if (spawned.some((enemy) => enemy.variant === 'carrier')) {
        setBossHealth(spawned.find((enemy) => enemy.variant === 'carrier')?.health ?? 0)
        setStatus('HEAVY CARRIER INBOUND · TARGET CORE SYSTEMS')
      }
      encounterCursor.current += 1
    }

    if (input.current.justPressed.has('KeyE')) triggerBarrel(1)
    if (input.current.justPressed.has('KeyQ') && bombs > 0) {
      setBombs((current) => current - 1)
      const cleared = spawnedEnemies.current.filter((enemy) => enemy.variant !== 'carrier' && enemy.z + (world.current.distance - enemy.bornAt) < 5).length
      spawnedEnemies.current = spawnedEnemies.current.filter((enemy) => enemy.variant === 'carrier' || enemy.z + (world.current.distance - enemy.bornAt) > 5)
      setEnemySpawns((current) => current.filter((enemy) => enemy.variant === 'carrier' || enemy.z + (world.current.distance - enemy.bornAt) > 5))
      setScore((current) => current + cleared * 8)
      setStatus('PULSE BOMB · AIRSPACE CLEARED')
    }

    if (input.current.keys.has('Space') && now - lastShot.current > 0.16) {
      lastShot.current = now
      const origin = player.current.position.clone()
      origin.z -= 1.2
      spawnLaser('player', origin)
    }

    for (const laser of lasers.current.values()) {
      if (!laser.alive) continue
      if (laser.owner === 'player') {
        for (const enemy of enemies.current.values()) {
          if (!enemy.alive) continue
          const dx = laser.position.x - enemy.position.x
          const dy = laser.position.y - enemy.position.y
          const dz = Math.abs(laser.position.z - enemy.position.z)
          if (Math.hypot(dx, dy) < enemy.radius && dz < 1.9) {
            laser.alive = false
            hitEnemy(enemy.id)
            break
          }
        }
      } else {
        const dx = laser.position.x - player.current.position.x
        const dy = laser.position.y - player.current.position.y
        const dz = Math.abs(laser.position.z - player.current.position.z)
        if (Math.hypot(dx, dy) < 0.9 && dz < 1.8) {
          laser.alive = false
          if (now < player.current.invincibleUntil) {
            setScore((current) => current + 5)
            setStatus('DEFLECTED')
          } else {
            damagePlayer(9)
            setStatus('HULL STRIKE · EVADE INCOMING FIRE')
          }
        }
      }
    }

    if (now - lastHudUpdate.current > 0.1) {
      lastHudUpdate.current = now
      setDistance(world.current.distance)
    }
    input.current.justPressed.clear()
  })

  const reset = () => {
    input.current = initialInput()
    world.current = initialWorld()
    player.current = initialPlayer()
    lasers.current.clear()
    enemies.current.clear()
    encounterCursor.current = 0
    spawnedEnemies.current = []
    gameOver.current = false
    setEnemySpawns([])
    setLaserSpecs([])
    setScore(0)
    setShield(100)
    setBombs(3)
    setBossHealth(0)
    setDistance(0)
    setTeammates({ lyra: true, rook: true, pip: true })
    setStatus('ESCORT THE CONVOY · CLEAR THE SKYLINE')
    setStageState('live')
    setRunning(true)
    setRunId((current) => current + 1)
  }

  return (
    <div className="game-shell">
      <Canvas
        key={runId}
        className="game-canvas"
        camera={{ position: [0, 1.1, 10], fov: 58, near: 0.1, far: 260 }}
        dpr={[1, 1.75]}
        gl={{ antialias: true, powerPreference: 'high-performance' }}
      >
        <color attach="background" args={['#061326']} />
        <fog attach="fog" args={['#061326', 36, 190]} />
        <ambientLight color="#7ebed0" intensity={0.5} />
        <directionalLight color="#b7e5ff" intensity={2.1} position={[-12, 18, 20]} />
        <directionalLight color="#4d79c4" intensity={1.4} position={[14, 4, -50]} />
        <GameScene
          flight={flight}
          enemySpawns={enemySpawns}
          laserSpecs={laserSpecs}
          onEnemyExpired={removeEnemy}
          onEnemyFire={(origin) => spawnLaser('enemy', origin)}
          onLaserExpired={expireLaser}
          registerEnemy={registerEnemy}
          unregisterEnemy={unregisterEnemy}
          registerLaser={registerLaser}
          unregisterLaser={unregisterLaser}
        />
      </Canvas>

      <div className="hud">
        <div className="hud__top">
          <div className="hud__cluster">
            <div><div className="hud__label">score</div><div className="hud__value hud__value--score">{score.toString().padStart(5, '0')}</div></div>
            <div><div className="hud__label">shield</div><div className="shield"><div className="shield__fill" style={{ width: `${shield}%` }} /></div></div>
          </div>
          <div><div className="hud__label">bombs</div><div className="hud__value">{bombs}</div></div>
        </div>
        <div className="hud__mission"><strong>SECTOR 01 · SKYLINE COAST</strong><span>R3F rail-shooter vertical slice · {Math.floor(distance)}m</span></div>
        <div className={`status${shield < 35 ? ' status--danger' : ''}`}>{status}</div>
        <div className="team">
          {TEAM.map((member) => (
            <div key={member.id} className={`team__member ${teammates[member.id] ? 'team__member--ready' : 'team__member--down'}`}>
              <span>{member.name}</span><span className="team__role">{teammates[member.id] ? member.role : 'down'}</span>
            </div>
          ))}
        </div>
        <div className="controls"><kbd>WASD</kbd> flight · <kbd>SPACE</kbd> fire · <kbd>SHIFT</kbd> boost<br /><kbd>E</kbd> roll · double-tap <kbd>A/D</kbd> · <kbd>Q</kbd> bomb</div>
      </div>

      {stageState !== 'live' && (
        <div className="overlay">
          <div className="overlay__card">
            <div className="overlay__eyebrow">MISSION {stageState === 'won' ? 'COMPLETE' : 'FAILED'}</div>
            <h1>{stageState === 'won' ? 'SKYLINE SECURED' : 'SIGNAL LOST'}</h1>
            <p>{stageState === 'won' ? `Carrier core neutralized. Final score ${score.toString().padStart(5, '0')}.` : 'The escort corridor is compromised. Recalibrate and fly again.'}</p>
            <button type="button" onClick={reset}>REDEPLOY</button>
          </div>
        </div>
      )}
    </div>
  )
}

interface GameSceneProps {
  flight: FlightRuntime
  enemySpawns: EnemySpawn[]
  laserSpecs: LaserSpec[]
  onEnemyExpired: (spawn: EnemySpawn) => void
  onEnemyFire: (origin: THREE.Vector3) => void
  onLaserExpired: (id: string) => void
  registerEnemy: (handle: EnemyHandle) => void
  unregisterEnemy: (id: string) => void
  registerLaser: (handle: LaserHandle) => void
  unregisterLaser: (id: string) => void
}

function GameScene({ flight, enemySpawns, laserSpecs, onEnemyExpired, onEnemyFire, onLaserExpired, registerEnemy, unregisterEnemy, registerLaser, unregisterLaser }: GameSceneProps) {
  return (
    <>
      <CameraRig flight={flight} />
      <Terrain world={flight.world} />
      <Arwing flight={flight} />
      <Reticle flight={flight} />
      {enemySpawns.map((spawn) => (
        <Enemy key={spawn.id} spawn={spawn} world={flight.world} onExpired={onEnemyExpired} onFire={onEnemyFire} register={registerEnemy} unregister={unregisterEnemy} />
      ))}
      {laserSpecs.map((laser) => (
        <Laser key={laser.id} {...laser} onExpired={onLaserExpired} register={registerLaser} unregister={unregisterLaser} />
      ))}
      <SceneEffects />
    </>
  )
}

