          key={index}
          ref={(mesh) => { tiles.current[index] = mesh }}
          rotation={[-Math.PI / 2, 0, 0]}
          position={[0, -3.5, -92 + index * TILE_LENGTH]}
          frustumCulled={false}
        >
          <planeGeometry args={[100, TILE_LENGTH, 36, 48]} />
          <shaderMaterial
            uniforms={uniforms}
            vertexShader={VERTEX_SHADER}
            fragmentShader={FRAGMENT_SHADER}
            side={THREE.DoubleSide}
          />
        </mesh>
      ))}

      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -3.15, -82]}>
