        <coneGeometry args={[8, 34, 5]} />
        <meshStandardMaterial color="#113a56" emissive="#082238" emissiveIntensity={0.6} flatShading />
      </mesh>
      <mesh position={[19, 7, -142]} rotation={[0, 0, -Math.PI / 2]}>
        <coneGeometry args={[10, 42, 5]} />
        <meshStandardMaterial color="#16445d" emissive="#082238" emissiveIntensity={0.6} flatShading />
      </mesh>
