const spawnEncounter = useCallback((encounter: Encounter, encounterIndex: number) => {
  const difficulty = getDifficulty(normalizedLevelProgress(world.current.distance))
  const wave = buildWave(encounter.enemies, difficulty)
  const spawned = wave.map((enemy, index) => ({
    ...enemy,
    id: `encounter-${encounterIndex}-${index}`,
    bornAt: world.current.distance,
  }))
  spawnedEnemies.current = [...spawnedEnemies.current, ...spawned]
